public class Main {
    public static void main(String[] args) {
        System.out.println("Area 3x4: " + area(3, 4));
        System.out.println("Total area: " + (area(3, 4) + area(2, 5)));

        int[] values = {4, 7};
        for (int v : values) {
            if (isEven(v)) {
                System.out.println(v + " is even");
            } else {
                System.out.println(v + " is odd");
            }
        }

        System.out.println("Max of 3, 9, 5: " + maxOfThree(3, 9, 5));
        System.out.println("Max of 8, 2, 8: " + maxOfThree(8, 2, 8));
    }

    static int area(int w, int h) {
        return w * h;
    }

    static boolean isEven(int n) {
        return n % 2 == 0;
    }

    static int maxOfThree(int a, int b, int c) {
        if (a >= b && a >= c) {
            return a;
        }
        if (b >= c) {
            return b;
        }
        return c;
    }
}

