import java.util.Arrays;

public class Main {
    public static void main(String[] args) {
        int count = 5;
        increment(count);
        System.out.println("count after increment: " + count);

        int[] nums = {1, 2, 3};
        doubleAll(nums);
        System.out.println("nums after doubleAll: " + Arrays.toString(nums));

        replace(nums);
        System.out.println("nums after replace: " + Arrays.toString(nums));
    }

    static void increment(int x) {
        x++;
        System.out.println("x inside increment: " + x);
    }

    static void doubleAll(int[] a) {
        for (int i = 0; i < a.length; i++) {
            a[i] *= 2;
        }
    }

    static void replace(int[] a) {
        a = new int[a.length];
        a[0] = 99;
        System.out.println("a inside replace: " + Arrays.toString(a));
    }
}

