import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;

public class Main {
    public static void main(String[] args) {
        int level = 7;
        bump(level);
        System.out.println("level after bump: " + level);

        int[] scores = {92, 85, 77};
        resetFirst(scores);
        System.out.println("scores after resetFirst: " + Arrays.toString(scores));

        List<String> cart = new ArrayList<>();
        cart.add("milk");
        cart.add("eggs");
        addItem(cart, "bread");
        System.out.println("cart after addItem: " + cart);
    }

    static void bump(int n) {
        n += 10;
        System.out.println("n inside bump: " + n);
    }

    static void resetFirst(int[] a) {
        a[0] = 0;
    }

    static void addItem(List<String> list, String item) {
        list.add(item);
    }
}
